<script setup>
import {computed,shallowRef} from 'vue';
import {DialogRoot,DialogPortal,DialogOverlay,DialogContent,DialogTitle,DialogDescription} from 'reka-ui';
import {invoiceStore,invoiceActions} from '../invoiceStore.js';
import {paymentStore} from '../lib/payment-store.js';
import {directory} from '../lib/expense-directory.js';
import {parseAssignmentWorkbook,reviewAssignmentImport,buildAssignmentTemplate} from '../lib/expense-assignment-import.js';
import {downloadBytes} from '../lib/file-utils.js';
const opened=shallowRef(false),source=shallowRef(null),review=shallowRef([]),selected=shallowRef([]),message=shallowRef('');
const usable=computed(()=>review.value.filter(i=>i.canApply));
async function load(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;try{source.value=parseAssignmentWorkbook(await file.arrayBuffer());preview();}catch(error){message.value=error.message;review.value=[];selected.value=[];}}
function preview(){review.value=reviewAssignmentImport(source.value,invoiceStore.ledger,paymentStore.rows,directory);selected.value=review.value.filter(i=>i.canApply).map(i=>i.id);message.value='只预览，尚未更新归属。未找到的记录可在保存原件/导入付款清单后再次导入。';}
function toggle(id,checked){selected.value=checked?[...new Set([...selected.value,id])]:selected.value.filter(x=>x!==id);}
function apply(){try{const r=invoiceActions.applyAssignmentImport(review.value,selected.value);message.value=`已更新 ${r.invoicesUpdated} 张发票、${r.paymentsUpdated} 笔付款的归属；原金额、报销和付款状态保留。`;review.value=reviewAssignmentImport(source.value,invoiceStore.ledger,paymentStore.rows,directory);selected.value=[];}catch(error){message.value=error.message;}}
function template(){downloadBytes(buildAssignmentTemplate(directory),'归属导入模板.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');}
</script>
<template><button type="button" class="btn" @click="opened=true">批量导入归属</button><DialogRoot v-model:open="opened"><DialogPortal><DialogOverlay class="assignment-overlay"/><DialogContent class="assignment-dialog"><header><DialogTitle>批量导入归属</DialogTitle><button type="button" class="btn" @click="opened=false">关闭</button></header><DialogDescription>核对发票或付款身份，只更新费用归属、工地、归属人及归属备注。原金额和报销、付款状态保留。</DialogDescription><div class="assignment-tools"><label class="btn-primary">选择归属导入表<input type="file" accept=".xlsx,.xls" hidden @change="load"/></label><button type="button" class="btn" @click="template">下载空白模板</button><button v-if="source" type="button" class="btn" @click="preview">重新预览</button><span>可更新 {{ usable.length }} 条 / 共 {{ review.length }} 条</span></div><p v-if="message" role="status">{{ message }}</p><div v-if="review.length" class="assignment-table"><table class="finance-table"><thead><tr><th>选择</th><th>核对结果</th><th>发票 / 付款</th><th>日期 / 金额</th><th>现有归属</th><th>导入后归属</th><th>归属人</th><th>问题说明</th></tr></thead><tbody><tr v-for="item in review" :key="item.id"><td><input type="checkbox" :disabled="!item.canApply" :checked="selected.includes(item.id)" :aria-label="'选择归属行 '+item.id" @change="toggle(item.id,$event.target.checked)"/></td><td>{{ item.status }}</td><td>{{ item.kind==='invoice'?item.row.number:item.row.seller }}</td><td>{{ item.row.date }}<br/>{{ item.row.total }} 元</td><td>{{ item.previous?.allocation }} {{ item.previous?.project }}</td><td>{{ item.patch?.allocation }} {{ item.patch?.project }}</td><td>{{ item.patch?.expenseOwner }}</td><td>{{ item.issues.join('；') }}</td></tr></tbody></table></div><footer><span>先选择并核对，点击确认后才保存。</span><button type="button" class="btn-primary" :disabled="!selected.length||invoiceStore.savingIntake" @click="apply">确认更新所选 {{ selected.length }} 条归属</button></footer></DialogContent></DialogPortal></DialogRoot></template>
<style scoped>.assignment-overlay{position:fixed;inset:0;background:#0f172a66;z-index:80}.assignment-dialog{position:fixed;inset:7vh 4vw auto;max-height:86vh;overflow:auto;z-index:81;background:white;border-radius:10px;padding:20px;outline:none}.assignment-dialog header,.assignment-tools,.assignment-dialog footer{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.assignment-dialog h2{margin:0;font-size:18px}.assignment-dialog p,.assignment-dialog footer{font-size:12px;color:#64748b}.assignment-tools{justify-content:flex-start;margin:14px 0}.assignment-table{overflow:auto;max-height:57vh}.assignment-dialog footer{padding-top:14px}.assignment-table td{max-width:260px;white-space:normal}</style>
